["message"] = "|cff979797|Hpratcopy|h[20:48:55]|h|r Scalecommander Emberthal says: While we slumbered, the kingdom of dragons rose and fell, the world was sundered, and the Aspects surrendered their power to stop Nel... to stop Deathwing.",
