},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:14]|h|r Naleidea Rivergleam says: A surprise attack! Guards! Arrest this handsome wizard!",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
