["serverTime"] = 1787892561,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:19]|h|r First Arcanist Thalyssra says: Otherwise, you might have come up with an excuse to refuse my proposal.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892566,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:19]|h|r Ebyssian says: Be at ease. He is an ally.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892566,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:23]|h|r Archmage Khadgar says: Apologies for my abrupt arrival. But the news I bring cannot wait for pleasantries.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892570,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:26]|h|r Lor'themar Theron says: Your proposal? I am quite certain it was I who begged for your hand in marriage, Thalyssra.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892573,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:29]|h|r Quest accepted: Whispers on the Winds",
["extraData"] = {
1,
11,
12,
["n"] = 3,
},
["b"] = 0,
