["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:34]|h|r First Arcanist Thalyssra says: Lor'themar Theron! You are such a creature of duty that you would have delayed our wedding over a crooked painting in Silvermoon.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892581,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:44]|h|r First Arcanist Thalyssra says: How fortunate I am that both our kingdoms witnessed our vows. Else you might try to deny that we ever exchanged them.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892591,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:53]|h|r Lor'themar Theron says: Deny the happiest moment of my life? Never.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892600,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:49:58]|h|r Lor'themar Theron says: Whether under the light of the sun or the rays of the moon, I will love you for all my days, Thalyssra.",
["extraData"] = {
13,
15,
16,
["n"] = 3,
},
["b"] = 0.6235294342041016,
["serverTime"] = 1787892605,
["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[21:50:07]|h|r First Arcanist Thalyssra says: As I will love you. No matter how many dragons try to distract us.",
["extraData"] = {
