},
{
["message"] = "|cff979797|Hpratcopy|h[11:40:41]|h|r Sendrax says: They were ruthless and powerful, killing countless dragons in ancient times.",
["serverTime"] = 1787942447,
["r"] = 1,
["extraData"] = {
