["timestamp"] = 17341.432,
["g"] = 1,
["r"] = 1,
},
{
["message"] = "|cff979797|Hpratcopy|h[14:38:18]|h|r Dervishian says: Thank you, Arkannalla. Dracthyr are a species out of time. Moments like these help us learn who we are.",
